        [270] = "Assert ($report.OnlineAttempted -and $network.Calls.Count -gt 0 -and $info.IsSupplementTarget -and -not $info.Enabled -and $info.Matches.Count -eq 1) 'Explicit disabled-file details did not trigger exact online supplementation.'",
        [271] = "Assert ($info.Matches[0].Dependencies[0].EnabledPaths.Count -eq 1 -and $report.DescribeFile($disabled).Contains('Disabled project')) 'Disabled-file detail lost its online dependency or caption.'",
