        [297] = "Assert ((FileInfo $report $disabled).Matches.Count -eq 0 -and (FileInfo $report $disabled).Candidates.Count -eq 1 -and -not $report.HasErrors) 'An unmatched explicit disabled target did not remain a candidate-only search.'",
        [300] = "Assert ($report.OnlineAttempted -and -not (FileInfo $report $mixedDisabled).IsSupplementTarget) 'Startup treated an unread disabled peer as a lookup/search target.'",
        [310] = "Assert ($reused.OnlineFiles.Count -eq 1 -and $reused.OnlineFiles[0].Matches[0].ProjectName -eq 'Cached project' -and $reused.OnlineRequests -eq 0 -and $reused.OnlineCheckedAtUtc.Year -eq 2020 -and $reused.OnlineNotes.Count -eq 0) 'Persistent platform mapping was rehashed or queried again for unchanged mods.'",
        [313] = "Assert (-not $rebuilt.OnlineAttempted -and $rebuilt.OnlineFiles.Count -eq 0) 'Manual tree rebuild retained stale platform lookup results.'",
        [328] = "Assert ($batch.OnlineFiles.Count -eq 205 -and @($batch.OnlineFiles|Where-Object {$_.IsSupplementTarget -and $_.Matches.Count -eq 2}).Count -eq 205) 'Manual index refresh omitted complete or disabled mod declarations after the old file cap.'",
        [329] = "Assert (@($batch.OnlineFiles|Where-Object {-not $_.Enabled -and $_.IsSupplementTarget}).Count -eq 7) 'Disabled mods were not indexed as manual declaration targets.'",
        [330] = "Assert (@($batch.OnlineFiles.Matches|Where-Object ProjectName -eq 'Batch project 204').Count -eq 1 -and @($batch.OnlineFiles.Matches|Where-Object ProjectName -eq 'CF batch project 204').Count -eq 1) 'Project titles beyond the first 100 IDs were not resolved on both platforms.'",
