        [335] = "Assert (@($network.Calls|Where-Object {$_ -eq 'https://api.modrinth.com/v2/version_files'}).Count -eq 3 -and @($network.Calls|Where-Object {$_ -like 'https://api.modrinth.com/v2/projects?*'}).Count -eq 5 -and @($network.Calls|Where-Object {$_ -eq 'https://api.curseforge.com/v1/mods'}).Count -eq 3) 'Full-folder matches and both platforms project metadata were not requested in batches.'",
        [337] = "if($network.Calls[$i] -eq 'https://api.modrinth.com/v2/version_files'){Assert ((ConvertFrom-Json $network.Bodies[$i]).hashes.Count -le 100) 'A version-hash API request exceeded its batch size.'}",
