        [347] = "Assert ($required.ProjectPaths.Count -eq 1 -and $required.MatchedPaths.Count -eq 0 -and $required.EnabledPaths.Count -eq 0 -and $required.Status.Contains('DifferentPinnedVersion')) 'Installed project identity was confused with satisfaction of a platform-pinned version.'",
