        [351] = "foreach($url in @('http://api.curseforge.com/v1/mods','https://evil.invalid/v1/mods','https://api.curseforge.com.evil.invalid/v1/mods','https://api.curseforge.com:444/v1/mods','https://user@api.curseforge.com/v1/mods','https://cdn.modrinth.com/v2/version_files')){Assert (-not [bool](Invoke-Static $online 'IsAllowedApi' @($url))) 'Credential boundary accepted a foreign host, port, protocol or userinfo.'}",
